module ActiveSupport;class Deprecation;module Disallowed;attr_writer:disallowed_warnings;def disallowed_warnings;@disallowed_warnings||=[];end;private;def deprecation_disallowed?(message)return false if explicitly_allowed?(message);return true if disallowed_warnings==:all;message&&disallowed_warnings.any? do |rule|case rule;when String,Symbol;message.include?(rule.to_s);when Regexp;rule.match?(message);end;end;end;def explicitly_allowed?(message)allowances=@explicitly_allowed_warnings.value;return false unless allowances;return true if allowances==:all;message&&Array(allowances).any? do |rule|case rule;when String,Symbol;message.include?(rule.to_s);when Regexp;rule.match?(message);end;end;end;end;end;end
